import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';

const Register = ({ setAuth }) => {
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!username || !email || !password) {
      setError('Please fill in all fields to create an account.');
      return;
    }

    localStorage.setItem('campusmart_auth', 'true');
    setAuth(true);
    navigate('/dashboard');
  };

  return (
    <main className="page-shell auth-page">
      <section className="auth-card">
        <div className="auth-copy">
          <p className="eyebrow">Create account</p>
          <h1>Register for CampusMart</h1>
          <p>Create a seller profile and start sharing listings with your campus community.</p>
        </div>

        <form onSubmit={handleSubmit} className="auth-form">
          {error && <div className="form-alert error-alert">{error}</div>}

          <label className="input-group">
            <span>Username</span>
            <input
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="Your username"
            />
          </label>

          <label className="input-group">
            <span>Email</span>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="your@email.com"
            />
          </label>

          <label className="input-group">
            <span>Password</span>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Create a strong password"
            />
          </label>

          <button type="submit" className="gradient-btn">
            Create Account
          </button>

          <div className="form-footer">
            <Link to="/login" className="subtle-link">
              Already have an account?
            </Link>
            <Link to="/" className="subtle-link">
              Learn more
            </Link>
          </div>
        </form>
      </section>
    </main>
  );
};

export default Register;
